values ('fq_omni_100', 'The Singularity', 'story', 'SS', 'OMNICORP', 'THE_SPIRE', 'SYSTEM STATUS: SINGULARITY ACHIEVED. (Location: The Spire, Director Sterling) All processes terminated. All systems integrated. All authority centralized. Return to the Spire. CEO Valerius confirms: YOU are now the operating system of Xylos. Efficiency is eternal. You are eternal.', '{"npc_id": "npc_omnicorp_executive", "name": "", "location": "THE_SPIRE"}'::jsonb, '{"min_level": 99, "reputation_required": 675, "required_quests": ["fq_omni_099"]}'::jsonb, '[{"type": "travel", "target": "THE_SPIRE", "count": 1, "desc": "Return to the Spire as the Singularity.", "description": "Travel to THE SPIRE. (Travel to: The Spire)"}, {"type": "interact", "target": "npc_omnicorp_executive", "count": 1, "desc": "Receive Singularity certification from CEO Valerius.", "description": "Speak with npc omnicorp executive. (Director Sterling at The Spire Executive Floor)"}]'::jsonb, '{"exp": 50000, "currency": 25000, "crd": 0, "rep": 10000, "items": [{"item_id": "resonanted_astral_phase_crystal", "quantity": 5}, {"item_id": "singularity_seal", "quantity": 1}], "reputation": 5}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_omnicorp.json', 98)
