values ('fq_shard_002', 'Pruning as Prayer', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'GLOWVINE_FOREST', 'Acolyte Mera, who tends the Glowvine Forest''s ritual paths, speaks with a reverence that the other factions find incomprehensible: the Forest Barklings are children of the Shard, born from the same corrupted soil that once was holy. They have grown wild because the Shard is dreaming — the Great Severance was not a catastrophe but a divine withdrawal, and its aftermath is the Shard''s sleeping breath reshaping the world. Each Barkling calmed is a prayer. Each cut must be made with the intention to restore, not to destroy.', '{"npc_id": "npc_acolyte_mera", "name": "Elder Malakor", "location": "GLOWVINE_FOREST"}'::jsonb, '{"min_level": 1, "reputation_required": 5, "required_quests": ["fq_shard_001"]}'::jsonb, '[{"type": "kill", "target": "FOREST_BARKLING", "count": 5, "description": "Prune Forest Barklings."}, {"type": "collect", "target": "bark_fragment", "count": 2, "description": "Collect bark fragment (x2). [Item: Bark Fragment]"}]'::jsonb, '{"exp": 55, "currency": 35, "crd": 0, "rep": 35, "items": [{"item_id": "vine_fiber", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_shard_003', false, NULL, NULL, NULL, 'quest_shard.json', 1)
