values ('fq_shard_005', 'The Shard Has Heard You', 'tutorial', 'D', 'CHILDREN_OF_THE_SHARD', 'SANCTUM', 'Oracle Seraphel — the Children''s seer, whose visions are trusted above all earthly counsel — has spoken to Elder Malakor: the Shard has heard your actions in the forest and found your soul-frequency resonant. This is the Children''s deepest honor. The Sanctum, hidden in the heart of the jungle, is where those found worthy are attuned to a specialization — not chosen, but revealed. The Shard shows you what you already are. Seraphel will perform the calibration. Come as you are. Come honestly.', '{"npc_id": "npc_shard_class_trainer", "name": "Oracle Seraphel", "location": "SANCTUM"}'::jsonb, '{"min_level": 4, "reputation_required": 20, "required_quests": ["fq_shard_004"], "required_items": ["recomendation_letters"]}'::jsonb, '[{"type": "interact", "target": "npc_shard_class_trainer", "count": 1, "description": "Receive calibration from Oracle Seraphel. (Oracle Seraphel at Sanctum Deep Chamber)"}, {"type": "interact", "target": "class_change_screen", "count": 1, "description": "Attune to your chosen path."}, {"type": "kill", "target": "GLOWVINE_SPRITE", "count": 3, "description": "Demonstrate harmony against the restless Hare. [Glowvine Sprite]"}]'::jsonb, '{"exp": 400, "currency": 200, "crd": 0, "rep": 150, "items": [{"item_id": "wpn_apprentice_staff", "quantity": 1}, {"item_id": "armor_cloth_robes", "quantity": 1}, {"item_id": "rare_emblem", "quantity": 1}, {"item_id": "echo_memory_core_low", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_006', true, 'on_quest_complete', 4, 'fq_shard_004', 'quest_shard.json', 4)
