values ('fq_shard_006', 'The Swamp Remembers the Sacred', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'SHARDROOT_SWAMP', 'Keeper Norn, the guardian of the Shardroot Swamp''s most ancient ritual sites, tells you what the swamp was before the Severance: a living archive, its waters infused with the Shard''s most subtle energies, home to creatures that carried the Shard''s memory in their blood. Now Industrial runoff from three competing factions chokes the waters. The Shard has not abandoned the swamp — the Children believe it is dreaming here, underneath the corruption. Enter. Begin the purification. Show the swamp it has not been forgotten.', '{"npc_id": "npc_shrine_keeper", "name": "Elder Malakor", "location": "SHARDROOT_SWAMP"}'::jsonb, '{"min_level": 5, "reputation_required": 20, "required_quests": ["fq_shard_005"]}'::jsonb, '[{"type": "travel", "target": "SHARDROOT_SWAMP", "count": 1, "description": "Enter the Shardroot Swamp."}, {"type": "collect", "target": "ancient_root_core", "count": 3, "description": "Collect ancient root core (x3). [Item: Ancient Root Core]"}]'::jsonb, '{"exp": 100, "currency": 60, "crd": 0, "rep": 60, "items": [{"item_id": "con_nutrient_ration", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_shard_007', false, NULL, NULL, NULL, 'quest_shard.json', 5)
