values ('fq_shard_009', 'Souls Between the Shard and the Void', 'story', 'D', 'CHILDREN_OF_THE_SHARD', 'SHARDROOT_SWAMP', 'Keeper Norn''s voice is the quietest of all the Children''s elders when he speaks of the Swamp Specters — he believes they are the souls of those who died in the Great Severance, still caught in the moment of the Shard''s fracture, unable to complete their journey because the energetic structure that would receive them was shattered. (Location: Shardroot Swamp, Keeper Norn) Cleansing them is not combat — it is a sacred act of completion. The ritual requires force because the Specters, like all things caught between worlds, resist release. Give them what they cannot give themselves: an ending.', '{"npc_id": "npc_shrine_keeper", "name": "Elder Malakor", "location": "SHARDROOT_SWAMP"}'::jsonb, '{"min_level": 8, "reputation_required": 35, "required_quests": ["fq_shard_008"]}'::jsonb, '[{"type": "kill", "target": "SWAMP_SPECTER", "count": 5, "description": "Cleanse Swamp Specters."}, {"type": "collect", "target": "specter_essence", "count": 3, "description": "Collect specter essence (x3). [Item: Specter Essence]"}]'::jsonb, '{"exp": 200, "currency": 110, "crd": 0, "rep": 110, "items": [{"item_id": "void_fragment", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_010', false, NULL, NULL, NULL, 'quest_shard.json', 8)
