values ('fq_shard_013', 'Purity Is Not Claimed, It Is Proven', 'story', 'C', 'CHILDREN_OF_THE_SHARD', 'FRAGMENT_SHRINE', 'The Shrine Avengers are drawn to void corruption — they are the Shard''s immune response, Oracle Seraphel says, targeting what the Shard recognizes as fundamentally hostile to its own nature. (Location: Fragment Shrine, Keeper Norn) The fact that they are attacking devotees of the Children along with obvious outsiders is itself a message: the Shard tests even its own. No one is exempt from the trial of purity simply because they believe they are pure. Face the Avengers honestly. What the Shard accepts, it accepts. What it rejects, it rejects.', '{"npc_id": "npc_shrine_keeper", "name": "Oracle Seraphel", "location": "FRAGMENT_SHRINE"}'::jsonb, '{"min_level": 12, "reputation_required": 55, "required_quests": ["fq_shard_012"]}'::jsonb, '[{"type": "kill", "target": "SHRINE_AVENGER", "count": 5, "description": "Prove purity against Shrine Avengers."}, {"type": "collect", "target": "specter_essence", "count": 1, "description": "Collect specter essence (x1). [Item: Specter Essence]"}]'::jsonb, '{"exp": 360, "currency": 190, "crd": 0, "rep": 200, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_014', false, NULL, NULL, NULL, 'quest_shard.json', 12)
