values ('fq_shard_014', 'The Oldest Ritual', 'story', 'C', 'CHILDREN_OF_THE_SHARD', 'FRAGMENT_SHRINE', 'The Shrine Guardian is not a creature that can be reasoned with or prayed past — it is a primordial construct that predates every faction, possibly predating the Aethelgardians themselves, placed by a power that even the Children''s oldest texts only reference obliquely. (Location: Fragment Shrine, Keeper Norn) Oracle Seraphel has spent years studying what earns its permission. The answer is simple, brutal, and theologically uncomfortable: the oldest ritual the Shard knows is confrontation. Face the Guardian directly. What you are will be revealed in the facing.', '{"npc_id": "npc_shrine_keeper", "name": "Oracle Seraphel", "location": "FRAGMENT_SHRINE"}'::jsonb, '{"min_level": 13, "reputation_required": 60, "required_quests": ["fq_shard_013"]}'::jsonb, '[{"type": "kill", "target": "SHRINE_GUARDIAN", "count": 2, "description": "Earn the Guardian''s permission. [Shrine Guardian]"}, {"type": "collect", "target": "aethel_core_shard", "count": 1, "description": "Collect aethel core shard (x1). [Item: Aethel Core Shard]"}]'::jsonb, '{"exp": 450, "currency": 240, "crd": 0, "rep": 240, "items": [{"item_id": "quantum_distortion_stone", "quantity": 1}], "reputation": 5}'::jsonb, false, false, 'fq_shard_015', false, NULL, NULL, NULL, 'quest_shard.json', 13)
