values ('fq_shard_016', 'The Shard''s Blessing and the Trial''s Weight', 'story', 'C', 'CHILDREN_OF_THE_SHARD', 'FRAGMENT_SHRINE', 'The Shrine Guardians do not distinguish between devotion and capability — the Shard''s blessing is irrelevant to them. (Location: Fragment Shrine, Keeper Norn) They test what you can do, not what you believe. Oracle Seraphel says this with something between respect and resignation: ''The Shard tests even its most faithful children, because the Shard does not gift what you have not earned.'' Three Guardians now patrol the Shrine''s outer ring. Prove that the blessing you carry is real by meeting the weight of the trial that carries it.', '{"npc_id": "npc_shrine_keeper", "name": "Oracle Seraphel", "location": "FRAGMENT_SHRINE"}'::jsonb, '{"min_level": 15, "reputation_required": 70, "required_quests": ["fq_shard_015"]}'::jsonb, '[{"type": "kill", "target": "SHRINE_GUARDIAN", "count": 3, "description": "Face the Guardian challenge. [Shrine Guardian]"}, {"type": "collect", "target": "aethel_core_shard", "count": 1, "description": "Collect aethel core shard (x1). [Item: Aethel Core Shard]"}]'::jsonb, '{"exp": 520, "currency": 290, "crd": 0, "rep": 310, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_shard_017', false, NULL, NULL, NULL, 'quest_shard.json', 15)
