values ('fq_shard_017', 'Memory Scattered, Memory Gathered', 'story', 'C', 'CHILDREN_OF_THE_SHARD', 'FRAGMENT_SHRINE', 'The scattered Shard fragments around the Shrine''s outer ring were displaced by a Concordium survey team three seasons ago — they were catalogued, handled without reverence, and then abandoned when the team was recalled during the Schism''s second wave. (Location: Fragment Shrine, Acolyte Mera) Acolyte Mera has been mapping their locations ever since. Each fragment is a memory of Xylos waiting to be returned to where the Shard can feel it. Recover them. The Shrine Avengers that patrol the area are themselves responding to the displaced fragments — they can sense the wrongness of it. So can you.', '{"npc_id": "npc_acolyte_mera", "name": "Oracle Seraphel", "location": "FRAGMENT_SHRINE"}'::jsonb, '{"min_level": 16, "reputation_required": 75, "required_quests": ["fq_shard_016"]}'::jsonb, '[{"type": "collect", "target": "specter_essence", "count": 4, "description": "Collect specter essence (x4). [Item: Specter Essence]"}, {"type": "kill", "target": "SHRINE_AVENGER", "count": 3, "description": "Clear Avenger patrols. [Shrine Avenger]"}]'::jsonb, '{"exp": 480, "currency": 260, "crd": 0, "rep": 260, "items": [{"item_id": "memory_fragment_chip", "quantity": 2}], "reputation": 5}'::jsonb, false, false, 'fq_shard_018', false, NULL, NULL, NULL, 'quest_shard.json', 16)
