values ('fq_shard_021', 'Where the Shard''s Heart Beats Loudest', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'The Heartwood Altar is the Children''s most sacred site — the place where, according to Elder Malakor''s oldest teachings, the Shard''s consciousness is most present in the physical world, the heart of the divine body that the Severance scattered across Xylos. Oracle Seraphel has seen your path in vision and confirmed: the Shard calls you here. Enter with reverence. What you encounter will test your commitment to the Children''s most fundamental truth: the Shard is a sleeping god, and those who come to its heart must come prepared to serve. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "HEARTWOOD_ALTAR"}'::jsonb, '{"min_level": 21, "reputation_required": 95, "required_quests": ["fq_shard_020"]}'::jsonb, '[{"type": "travel", "target": "HEARTWOOD_ALTAR", "count": 1, "description": "Enter the Heartwood Altar."}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 1650, "currency": 825, "crd": 247, "rep": 515, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 10}'::jsonb, false, false, 'fq_shard_022', false, NULL, NULL, NULL, 'quest_shard.json', 20)
