values ('fq_shard_022', 'The Altar''s Ancient Wardens', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'The Aethel Behemoths that roam the Heartwood Altar''s outer grounds are not merely large creatures — the Children''s scripture names them the Altar''s first guardians, placed here in an age before the Severance to protect the site from those who would harvest it. They have been corrupted by centuries of proximity to the Altar''s raw aethel output without the guidance of the Shard''s active consciousness. Oracle Seraphel believes calming them — even through forced combat — restores a small measure of what was taken from them. Proceed with that understanding. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "HEARTWOOD_ALTAR"}'::jsonb, '{"min_level": 22, "reputation_required": 105, "required_quests": ["fq_shard_021"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 2, "description": "Calm Behemoth guardians. [Aethel Behemoth]"}, {"type": "collect", "target": "raw_aethel_core", "count": 1, "description": "Collect raw aethel core (x1). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 1700, "currency": 850, "crd": 255, "rep": 530, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_shard_023', false, NULL, NULL, NULL, 'quest_shard.json', 21)
