insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_023', 'The Leviathan That Refuses to Sleep', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'A Sunken Aethel Leviathan has surfaced near the Heartwood Altar''s sacred wells — drawn, Elder Malakor believes, by the Shard''s increasing resonance as the Children''s work at the site progresses. In ancient scripture, the Leviathan''s appearance is an omen: the Shard is stirring in its sleep, and the great creatures of the deep respond to that stirring before any lesser being can feel it. Guide it back to the deep, by whatever means the Shard permits. Its surfacing should not become a permanent disruption. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "HEARTWOOD_ALTAR"}'::jsonb, '{"min_level": 23, "reputation_required": 115, "required_quests": ["fq_shard_022"]}'::jsonb, '[{"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 1, "description": "Guide the Leviathan. [Sunken Aethel Leviathan]"}, {"type": "collect", "target": "leviathan_scale", "count": 2, "description": "Collect leviathan scale (x2). [Item: Leviathan Scale]"}]'::jsonb, '{"exp": 1750, "currency": 875, "crd": 262, "rep": 545, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_shard_024', false, NULL, NULL, NULL, 'quest_shard.json', 22)
