values ('fq_shard_025', 'Mastery Is Acceptance of the Trial', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'The Shrine Wardens at the Heartwood Altar are more powerful than those at the Fragment Shrine — the Shard''s presence here is stronger, and so its tests are correspondingly harder. Elder Malakor''s doctrine on mastery is clear: it is not the defeating of the trial that matters, but the willingness to face it fully, without protection from the outcome. You have been prepared by the Fragment Shrine''s trials. Now the Heartwood tests what that preparation actually made you. Face the Wardens and Avengers with everything you have brought to this sacred ground. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "HEARTWOOD_ALTAR"}'::jsonb, '{"min_level": 25, "reputation_required": 135, "required_quests": ["fq_shard_024"]}'::jsonb, '[{"type": "kill", "target": "SHRINE_WARDEN", "count": 4, "description": "Master the Wardens. [Shrine Warden]"}, {"type": "kill", "target": "SHRINE_AVENGER", "count": 3, "description": "Master the Avengers. [Shrine Avenger]"}]'::jsonb, '{"exp": 1850, "currency": 925, "crd": 277, "rep": 575, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_shard_026', false, NULL, NULL, NULL, 'quest_shard.json', 24)
