values ('fq_shard_026', 'The Shard Speaks in Lightning', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'AETHEL_STORM_BELT', 'The Aethel Storm Belt is where the Children of the Shard have always sent their most devoted pilgrims after completing the Heartwood Altar''s trials — not because it is safe, but because the Shard speaks most clearly in the electromagnetic storms that rage here, using lightning as its language. Oracle Seraphel''s vision of your path ends here, in the storm-light. What comes next, she says, is yours to discover. Enter the Storm Belt. Listen for what the lightning says to those who have earned the right to hear it. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "AETHEL_STORM_BELT"}'::jsonb, '{"min_level": 25, "reputation_required": 145, "required_quests": ["fq_shard_025"]}'::jsonb, '[{"type": "travel", "target": "AETHEL_STORM_BELT", "count": 1, "description": "Enter the Storm Belt. (Travel to: Aethel Storm Belt)"}, {"type": "collect", "target": "monster_material", "count": 2, "description": "Collect monster material (x2). [Item: Monster Material]"}]'::jsonb, '{"exp": 1850, "currency": 925, "crd": 277, "rep": 575, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_shard_027', false, NULL, NULL, NULL, 'quest_shard.json', 25)
