values ('fq_shard_029', 'The Altar Must Be Consecrated Again', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'HEARTWOOD_ALTAR', 'The Heartwood Altar''s consecration requires periodic renewal — a ritual the Children have maintained since before their founding, one that involves returning the corrupted Behemoths'' aethel energy to the Altar''s sacred wells as an offering of purification. The process is not gentle; the Behemoths resist because the corruption inside them resists release. But the Altar needs what they carry, and the Altar is the Shard''s nearest beating heart. This is the Children''s highest responsibility. Honor it. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "HEARTWOOD_ALTAR"}'::jsonb, '{"min_level": 28, "reputation_required": 175, "required_quests": ["fq_shard_028"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 3, "description": "Purify Behemoths. [Aethel Behemoth]"}, {"type": "collect", "target": "raw_aethel_core", "count": 1, "description": "Collect raw aethel core (x1). [Item: Raw Aethel Core]"}]'::jsonb, '{"exp": 2000, "currency": 1000, "crd": 300, "rep": 620, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 10}'::jsonb, false, false, 'fq_shard_030', false, NULL, NULL, NULL, 'quest_shard.json', 28)
