values ('fq_shard_030', 'The Spirit Rises to Its Next Form', 'story', 'B', 'CHILDREN_OF_THE_SHARD', 'SANCTUM', 'Oracle Seraphel has announced the Ascension of Spirit ceremony to the full Sanctum congregation — an announcement that Elder Malakor himself blessed, which the Children understand as the Shard''s own confirmation. The Ascension is not a promotion; it is a recognition that what you have already become deserves a name and a form that reflects it. The trials ahead in the Cradle Expanse will be harder than anything the Altar or the Storm Belt required. The Shard does not give you more than it believes you can carry. Return to the Sanctum and receive what is yours.', '{"npc_id": "npc_shard_class_trainer", "name": "Oracle Seraphel", "location": "SANCTUM"}'::jsonb, '{"min_level": 29, "reputation_required": 185, "required_quests": ["fq_shard_029"]}'::jsonb, '[{"type": "interact", "target": "npc_shard_class_trainer", "count": 1, "description": "Receive Ascension. (Oracle Seraphel at Sanctum Deep Chamber)"}, {"type": "kill", "target": "RESONANCE_ECHO", "count": 1, "description": "Harmonize again. [Resonance Echo]"}, {"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 1, "description": "Guide Leviathan trial. [Sunken Aethel Leviathan]"}]'::jsonb, '{"exp": 2050, "currency": 1025, "crd": 307, "rep": 635, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 10}'::jsonb, false, false, 'fq_shard_031', true, 'on_quest_complete', 29, 'fq_shard_029', 'quest_shard.json', 29)
