values ('fq_shard_032', 'The Drake That Burns What the Shard Needs', 'story', 'A', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'The Ashen Drake in the Cradle Expanse is burning through the aethel-rich vegetation that the Children have identified as part of the Shard''s external nervous system — the network of plant life that carries the Shard''s subtle signals across Xylos. Every acre the Drake burns is another section of the network the Shard cannot hear through. Oracle Seraphel''s instruction is reluctant but clear: the Drake must be pacified by any means the Shard allows. What is lost in the Drake''s release must be weighed against what is saved in the network. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 31, "reputation_required": 220, "required_quests": ["fq_shard_031"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Pacify. [Ashen Drake]"}, {"type": "collect", "target": "drake_heart", "count": 1, "description": "Collect drake heart (x1). [Item: Drake Heart]"}]'::jsonb, '{"exp": 2150, "currency": 1075, "crd": 537, "rep": 665, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 25}'::jsonb, false, false, 'fq_shard_033', false, NULL, NULL, NULL, 'quest_shard.json', 31)
