insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_034', 'When the Sacred Is Corrupted', 'story', 'A', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'The Corrupted Behemoths in the Cradle Expanse are what Elder Malakor calls ''the Children''s deepest grief made flesh'' — sacred creatures that have been twisted by the Concordium''s aethel harvesting operations, their ancient connection to the Shard replaced with raw instability. They are not enemies. They are the Shard''s children, suffering from what others have done to the world the Shard created. The cleansing requires combat because the corruption inside them is aggressive. Remember, as you fight: you are not punishing them. You are releasing them. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 33, "reputation_required": 270, "required_quests": ["fq_shard_033"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 2, "description": "Cleanse. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2250, "currency": 1125, "crd": 546, "rep": 695, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_shard_035', false, NULL, NULL, NULL, 'quest_shard.json', 33)
