values ('fq_shard_036', 'Sanctifying What Others Fight Over', 'story', 'A', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'The Cradle Expanse is the most contested zone on Xylos — every faction has soldiers here, every faction claims tactical rights to its resources. The Children of the Shard have a different claim. The Expanse was sacred ground before any of these factions existed, and the Shard''s presence here predates the Concordium''s infrastructure by millennia. Oracle Seraphel''s sanctification mission requires clearing the Rift Stalkers and Void Channelers that the other factions'' conflict has attracted. Sanctified ground does not permit what these creatures carry. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 35, "reputation_required": 320, "required_quests": ["fq_shard_035"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_RIFT_STALKER", "count": 6, "description": "Harmonize. [Aethel Rift Stalker]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Purify taint. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2350, "currency": 1175, "crd": 587, "rep": 725, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_shard_037', false, NULL, NULL, NULL, 'quest_shard.json', 35)
