values ('fq_shard_039', 'The Void Does Not Get to Stay', 'story', 'A', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'A coordinated incursion of Abyssal Reavers and Void Channelers has pushed into the Cradle Expanse''s sacred zones — the Channelers directing the Reavers with a precision that suggests external coordination, possibly from the approaching Abyss Harbinger the Concordium has been tracking. Elder Malakor is uncharacteristically sharp in his instruction: ''The void does not get to stay where the Shard breathes. Not one of them. Not one.'' The cleansing must be total. What the void carries corrupts everything it touches, and the Expanse cannot afford any lingering taint. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 38, "reputation_required": 395, "required_quests": ["fq_shard_038"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 6, "description": "Cleanse. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 3, "description": "Silence. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2500, "currency": 1250, "crd": 606, "rep": 770, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 25}'::jsonb, false, false, 'fq_shard_040', false, NULL, NULL, NULL, 'quest_shard.json', 38)
