values ('fq_shard_040', 'The Symbiosis That Is Mastery', 'story', 'A', 'CHILDREN_OF_THE_SHARD', 'SANCTUM', 'Elder Malakor speaks the words that the entire Sanctum congregation has gathered to hear: you are now, in the Children''s truest doctrine, a Master of Symbiosis — one who has moved through the sacred world not as a harvester or a conqueror but as the Shard''s partner, giving and receiving in equal measure. The final trial requires you to face the Drake, the Behemoth, and the Leviathan — the three great creatures whose guidance represents the deepest form of the Children''s creed — and return their energy to the Shard one last time before ascending to what awaits in the Void Echo Chasm. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "SANCTUM"}'::jsonb, '{"min_level": 39, "reputation_required": 420, "required_quests": ["fq_shard_039"]}'::jsonb, '[{"type": "kill", "target": "ASHEN_DRAKE", "count": 1, "description": "Guide Drake. [Ashen Drake]"}, {"type": "kill", "target": "AETHEL_BEHEMOTH", "count": 1, "description": "Guide Behemoth. [Aethel Behemoth]"}, {"type": "kill", "target": "SUNKEN_AETHEL_LEVIATHAN", "count": 1, "description": "Guide Leviathan. [Sunken Aethel Leviathan]"}]'::jsonb, '{"exp": 2550, "currency": 1275, "crd": 637, "rep": 785, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 25}'::jsonb, false, false, 'fq_shard_041', false, NULL, NULL, NULL, 'quest_shard.json', 39)
