values ('fq_shard_042', 'The Wound Is Full of What Entered It', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'The Void Echo Chasm has been filling with void energy since the Great Severance tore it open — centuries of accumulation, layer upon layer of Void Reavers and Channelers making their home in the scar the Shard could not close. Elder Malakor says the Chasm cannot be healed from outside; the wound must be cleansed from within. Each Reaver destroyed is a fraction of the void removed from the place where the Shard is most vulnerable. This is the Children''s deepest act of devotion: cleaning the wound from inside it. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 41, "reputation_required": 495, "required_quests": ["fq_shard_041"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 6, "description": "Cleanse. [Void Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 4, "description": "Purify. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 2650, "currency": 1325, "crd": 642, "rep": 815, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_shard_043', false, NULL, NULL, NULL, 'quest_shard.json', 41)
