insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_043', 'The Void Has Children Too', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'The Aethel Abyssal Reavers deep in the Chasm are more developed than those in the Expanse — they have been in the wound longer, grown more fully from the void energy that filled it. (Location: Void Echo Chasm, High Priestess Lyr) Oracle Seraphel says, with a kind of awed disquiet, that the void is trying to do what the Shard does: create children from its own substance. The Children of the Shard cannot permit this. Not because the void does not have the right to create — but because what it creates in the Shard''s wound is a desecration of the Shard''s most sacred space. End them with full understanding of what you are ending.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 42, "reputation_required": 545, "required_quests": ["fq_shard_042"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Harvest. [Aethel Abyssal Reaver]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 2, "description": "Collect raw aethel fragment (x2). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2700, "currency": 1350, "crd": 654, "rep": 830, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_044', false, NULL, NULL, NULL, 'quest_shard.json', 42)
