insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_044', 'Sacred Creatures in a Void-Touched Place', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'Corrupted Behemoths have descended into the Void Echo Chasm — the most corrupted these ancient guardians have ever been, their connection to the Shard almost entirely replaced by void energy. Elder Malakor weeps, quietly, when he reviews the scouting reports. These were the Shard''s most devoted natural guardians. The void has turned them into weapons against the place they were meant to protect. The purification here is the most difficult the Children undertake: releasing what you love most from what it has been forced to become. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 43, "reputation_required": 595, "required_quests": ["fq_shard_043"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Purge. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "raw_aethel_fragment", "count": 1, "description": "Collect raw aethel fragment (x1). [Item: Raw Aethel Fragment]"}]'::jsonb, '{"exp": 2750, "currency": 1375, "crd": 666, "rep": 845, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_shard_045', false, NULL, NULL, NULL, 'quest_shard.json', 43)
