insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_045', 'What Fragments Souls in the Wound', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'The Soul Fragmenters in the Chasm''s deep zone are entities the Children''s theology names specifically and fearfully — creatures that consume the soul-fragments of those who died in the Great Severance, the same fragments that the Swamp Specters in the Shardroot Swamp carry in unresolved form. (Location: Void Echo Chasm, High Priestess Lyr) A Soul Fragmenter devours those fragments permanently, erasing souls that the Shard has been trying to reclaim for centuries. This is the worst thing in the Chasm. Elder Malakor names this exorcism the Children''s most sacred act. Do not fail here.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 44, "reputation_required": 645, "required_quests": ["fq_shard_044"]}'::jsonb, '[{"type": "kill", "target": "SOUL_FRAGMENTER", "count": 2, "description": "Exorcise. [Soul Fragmenter]"}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 2800, "currency": 1400, "crd": 678, "rep": 860, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_shard_046', false, NULL, NULL, NULL, 'quest_shard.json', 44)
