values ('fq_shard_046', 'Time Itself Is Twisted Here', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'Chrono Wraiths exist where time has been fractured by extreme aethel disruption — in the Void Echo Chasm, where the Great Severance''s initial detonation warped the temporal substrate, time does not flow normally. The Wraiths are echoes of the Severance moment itself, still replaying in the wound''s deepest layers. Oracle Seraphel says that banishing them is, theologically, an act of mercy to the moment of the Shard''s greatest pain: allowing the Severance to finally, partially, end. Each Wraith banished is a piece of that catastrophe released. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 45, "reputation_required": 695, "required_quests": ["fq_shard_045"]}'::jsonb, '[{"type": "kill", "target": "CHRONO_WRAITH", "count": 2, "description": "Banish. [Chrono Wraith]"}, {"type": "collect", "target": "core_fragment", "count": 1, "description": "Collect core fragment (x1). [Item: Core Fragment]"}]'::jsonb, '{"exp": 2850, "currency": 1425, "crd": 690, "rep": 875, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_047', false, NULL, NULL, NULL, 'quest_shard.json', 45)
