values ('fq_shard_047', 'A Jotunn at the Bottom of the World', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'A Gigantic Jotunn — creatures the Children call ''the mountains'' because they were old when mountains were young — has descended into the Void Echo Chasm and made the deepest reachable zone its home. It is not void-corrupted; it is ancient and territorial and utterly indifferent to the Shard''s purposes. Elder Malakor says the Jotunn''s presence is not spiritual — it is geological, a creature of the world''s deep stone. But it blocks the passage the Children need to complete the Chasm''s cleansing. Pacify it by any means the Shard provides. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 46, "reputation_required": 745, "required_quests": ["fq_shard_046"]}'::jsonb, '[{"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Pacify. [Gigantic Jotunn]"}, {"type": "collect", "target": "monster_material", "count": 1, "description": "Collect monster material (x1). [Item: Monster Material]"}]'::jsonb, '{"exp": 2900, "currency": 1450, "crd": 702, "rep": 890, "items": [{"item_id": "aethel_core_shard", "quantity": 2}], "reputation": 50}'::jsonb, false, false, 'fq_shard_048', false, NULL, NULL, NULL, 'quest_shard.json', 46)
