values ('fq_shard_051', 'No Void Remains in the Sacred Wound', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'Elder Malakor''s instruction for this phase of the Chasm''s purification is absolute: total void removal from the designated sectors. (Location: Void Echo Chasm, High Priestess Lyr) Every Reaver, every Channeler, without exception. The Shard cannot begin to heal the wound while any void entity remains active inside it — the presence of even one Channeler continues the energy drain that has kept the Shard sleeping longer than it should have. Oracle Seraphel says the Shard can feel you working. She says it feels like a breath returning. Do not let it stop here.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 51, "reputation_required": 945, "required_quests": ["fq_shard_050"]}'::jsonb, '[{"type": "kill", "target": "VOID_REAVER", "count": 8, "description": "Purify. [Void Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Purify. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 3150, "currency": 1575, "crd": 762, "rep": 965, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_052', false, NULL, NULL, NULL, 'quest_shard.json', 50)
