values ('fq_shard_054', 'Purifying the Wound at Its Deepest', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'The deepest reachable layers of the Void Echo Chasm contain the highest concentration of Abyssal Reavers and Void Reavers in any known location on Xylos. Oracle Seraphel''s assessment is direct: these are not random creatures but the void''s deliberate concentration of force at the wound''s center, a defense against exactly what the Children are attempting. The Shard''s awakening depends on this purification being complete. Ten Abyssal Reavers, six Void Reavers, removed from the place they were put to prevent this moment. This is the Shard''s war, fought in your name. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 54, "reputation_required": 1095, "required_quests": ["fq_shard_053"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 10, "description": "Purify. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "VOID_REAVER", "count": 6, "description": "Purify. [Void Reaver]"}]'::jsonb, '{"exp": 3300, "currency": 1650, "crd": 798, "rep": 1010, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_055', false, NULL, NULL, NULL, 'quest_shard.json', 53)
