values ('fq_shard_059', 'The Harbinger Reaches the Wound', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'VOID_ECHO_CHASM', 'The Abyss Harbinger has entered the Void Echo Chasm. Elder Malakor falls to his knees when Oracle Seraphel reports this — not in despair, but in the posture of the deepest prayer the Children know, the one reserved for moments when the Shard''s fate is at stake. This is the confrontation the Children of the Shard exist to reach: the void that has occupied the Shard''s wound since the Severance, given its ultimate form, encountered at last by one who has walked every step of the Shard''s path to this moment. Defeat it. Bring the wound one step closer to healing. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "VOID_ECHO_CHASM"}'::jsonb, '{"min_level": 59, "reputation_required": 1345, "required_quests": ["fq_shard_058"]}'::jsonb, '[{"type": "kill", "target": "ABYSS_HARBINGER", "count": 1, "description": "DEFEAT HARBINGER. [Abyss Harbinger]"}, {"type": "collect", "target": "void_core", "count": 1, "description": "Collect void core (x1). [Item: Void Core]"}]'::jsonb, '{"exp": 3550, "currency": 1775, "crd": 858, "rep": 1085, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_shard_060', false, NULL, NULL, NULL, 'quest_shard.json', 58)
