values ('fq_shard_060', 'The Line Where Xylos Was Torn', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'SEVERANCE_FAULTLINE', 'The Severance Faultline is the geological scar left by the Great Severance''s shockwave — the line in Xylos''s crust where the Aethel Siphon''s overload physically split the planet''s substrate. The Shard''s deep roots run along this scar, attempting to reconnect what was severed, and Oracle Seraphel says that supporting those roots — clearing the Carapace creatures that are feeding on the faultline''s exposed aethel substrate — is the Children''s work here. Align with the Shard''s effort. Enter the Faultline where the world was torn. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "SEVERANCE_FAULTLINE"}'::jsonb, '{"min_level": 60, "reputation_required": 1395, "required_quests": ["fq_shard_059"]}'::jsonb, '[{"type": "travel", "target": "SEVERANCE_FAULTLINE", "count": 1, "description": "Enter. (Travel to: Severance Faultline, Shattered Heart)"}, {"type": "collect", "target": "thick_gel", "count": 3, "description": "Collect thick gel (x3). [Item: Thick Gel]"}]'::jsonb, '{"exp": 3600, "currency": 1800, "crd": 870, "rep": 1100, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_061', false, NULL, NULL, NULL, 'quest_shard.json', 59)
