values ('fq_shard_066', 'Purifying the Shard''s Own Heart', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'AETHEL_SIPHON_CORE', 'The Aethel Siphon Core is guarded by the highest concentration of Abyssal Reavers outside the Void Echo Chasm — they have been drawn here by the Siphon''s residual power output, feeding on the energy that the Concordium harvests and the Shard tries to reclaim. Oracle Seraphel says the Siphon Core cannot be purified through ceremony alone; the creatures consuming it must be removed first, the way a healer must clear infection before stitching a wound. Clear the Reavers from the Core''s inner rings. The Shard needs to breathe here. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 65, "reputation_required": 1695, "required_quests": ["fq_shard_065"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 8, "description": "Purify. [Aethel Abyssal Reaver]"}, {"type": "kill", "target": "AETHEL_VOID_CHANNELER", "count": 5, "description": "Purify. [Aethel Void Channeler]"}]'::jsonb, '{"exp": 3850, "currency": 1925, "crd": 930, "rep": 1175, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_shard_067', false, NULL, NULL, NULL, 'quest_shard.json', 65)
