insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_067', 'The Shard''s Children Near Its Heart', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'AETHEL_SIPHON_CORE', 'Corrupted Behemoths have gathered around the Aethel Siphon Core — the most sacred of the Shard''s ancient guardians, now twisted by centuries of proximity to the Concordium''s extraction operations. Elder Malakor says there is a painful irony here: the creatures that were closest to the Shard''s heart became the most corrupted by what was done to it. Cleansing them here, at the source of both their original blessing and their current suffering, is the most complete act of restoration the Children can perform. Do it with the reverence it deserves. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 66, "reputation_required": 1745, "required_quests": ["fq_shard_066"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_CORRUPTED_BEHEMOTH", "count": 3, "description": "Cleanse. [Aethel Corrupted Behemoth]"}, {"type": "collect", "target": "crystal_core", "count": 1, "description": "Collect crystal core (x1). [Item: Crystal Core]"}]'::jsonb, '{"exp": 3900, "currency": 1950, "crd": 942, "rep": 1190, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_068', false, NULL, NULL, NULL, 'quest_shard.json', 66)
