values ('fq_shard_069', 'The Core''s Own Guardian Must Be Named', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'AETHEL_SIPHON_CORE', 'Deeper in the Aethel Siphon Core, something waits that Oracle Seraphel has seen in vision but cannot name — a presence that the Shard itself has placed here as its final line of defense, more ancient and more powerful than the Wardens, Guardians, or Avengers the Children have faced before. It does not respond to the Children''s liturgy. It responds only to demonstration of purpose. The materials you gather from the Core''s outer zones are the offering that opens the path to it. Bring them. Show the guardian what you are here to do. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "AETHEL_SIPHON_CORE"}'::jsonb, '{"min_level": 68, "reputation_required": 1845, "required_quests": ["fq_shard_068"]}'::jsonb, '[{"type": "collect", "target": "monster_material", "count": 3, "description": "Collect monster material (x3). [Item: Monster Material]"}, {"type": "kill", "target": "GIGANTIC_JOTUNN", "count": 1, "description": "Guard. [Gigantic Jotunn]"}]'::jsonb, '{"exp": 4000, "currency": 2000, "crd": 966, "rep": 1220, "items": [{"item_id": "aethel_core_shard", "quantity": 3}], "reputation": 50}'::jsonb, false, false, 'fq_shard_070', false, NULL, NULL, NULL, 'quest_shard.json', 68)
