values ('fq_shard_070', 'The Titan That Holds the Expanse', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'A Gravity Titan — a creature of such mass and gravitational influence that the Concordium classified its existence as a geological event rather than a biological one — has taken up residence in the Cradle Expanse''s central zone, creating a gravity well that is disrupting the aethel flow patterns the Children have been trying to restore. The Shard''s electromagnetic network cannot function correctly while a gravitational anomaly this large sits in its path. Oracle Seraphel has consulted with Elder Malakor for three days. The conclusion is the same: it must be moved. Guide it away from the Expanse with whatever means the Shard provides. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 69, "reputation_required": 1895, "required_quests": ["fq_shard_069"]}'::jsonb, '[{"type": "kill", "target": "GRAVITY_TITAN", "count": 1, "description": "TRANQUILIZE TITAN. [Gravity Titan]"}, {"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Clear. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 4050, "currency": 2025, "crd": 978, "rep": 1235, "items": [{"item_id": "aethel_core_shard", "quantity": 1}], "reputation": 50}'::jsonb, false, false, 'fq_shard_071', false, NULL, NULL, NULL, 'quest_shard.json', 69)
