insert into public.quests (id, title, type, rank, faction, region, description, quest_giver, requirements, objectives, rewards, repeatable, daily, quest_chain_next, popup, popup_trigger, popup_level, popup_prerequisite, source_file, sort_order)
values ('fq_shard_078', 'Endless Duty in the Expanse', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'The Void does not stop sending Abyssal Reavers into the Cradle Expanse. Elder Malakor says this without despair: the Children of the Shard are called to endless service, not limited service. Every Reaver cleared is a sacred act, regardless of how many more follow. The Expanse is sacred ground. The Children''s duty to it is sacred. This is what being a Child of the Shard means in practice, stripped of ceremony: showing up, again and again, to do the work the Shard requires. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 77, "reputation_required": 2295, "required_quests": ["fq_shard_077"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Sacred duty. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [], "reputation": 50}'::jsonb, false, false, 'fq_shard_079', false, NULL, NULL, NULL, 'quest_shard.json', 77)
