values ('fq_shard_080', 'Sacred Vigil: The Expanse Holds', 'story', 'S', 'CHILDREN_OF_THE_SHARD', 'CRADLE_EXPANSE', 'The Cradle Expanse requires constant vigilance — not because the Children failed in their earlier cleansings, but because the void is patient in ways the Children respect and oppose simultaneously. Elder Malakor says the vigil is itself a form of prayer: maintaining awareness of what threatens sacred ground, meeting that threat each time it comes, without resentment for its return. The Expanse holds as long as the Children hold it. This is not burden. This is devotion. Quest giver: High Priestess Lyr at Sanctum Inner Chamber.', '{"npc_id": "npc_high_priest", "name": "Oracle Seraphel", "location": "CRADLE_EXPANSE"}'::jsonb, '{"min_level": 79, "reputation_required": 2395, "required_quests": ["fq_shard_079"]}'::jsonb, '[{"type": "kill", "target": "AETHEL_ABYSSAL_REAVER", "count": 5, "description": "Sacred duty. [Aethel Abyssal Reaver]"}]'::jsonb, '{"exp": 5000, "currency": 2500, "crd": 1250, "rep": 2000, "items": [], "reputation": 50}'::jsonb, false, false, 'fq_shard_081', false, NULL, NULL, NULL, 'quest_shard.json', 79)
