values ('QUEST_NEUTRAL_STORY_002', 'Strings Above the Stars', 'story', 'A', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'The weapons cache investigation pointed to a shadow organization manipulating multiple factions simultaneously. (Location: Nexus Core, Commander Sera Holt) Commander Sera Holt requests a deep infiltration mission into a known smuggling hub. Gather intelligence on the organization''s structure before they go underground.', '{"npc_id": "NPC_NEXUS_QUESTGIVER_COMMANDER", "name": "Commander Sera Holt", "location": "Pax Nexus — The Sentinel Outpost"}'::jsonb, '{"min_level": 20, "reputation_required": 0, "required_quests": ["QUEST_NEUTRAL_STORY_001"], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "travel", "target": "CONFLICT_ZONE_HUB", "count": 1, "description": "Infiltrate the suspected smuggling hub in the conflict zone"}, {"type": "stealth", "target": "SHADOW_ORG_INTEL", "count": 4, "description": "Gather {count} intelligence fragments without alerting guards"}, {"type": "kill", "target": "SHADOW_ENFORCER", "count": 8, "description": "Eliminate {count} shadow enforcers who spot you during extraction"}, {"type": "interact", "target": "NPC_NEXUS_QUESTGIVER_COMMANDER", "count": 1, "description": "Deliver intelligence to Commander Holt (Commander Sera Holt at Pax Nexus — The Sentinel Outpost)"}]'::jsonb, '{"exp": 2000, "currency": 0, "crd": 800, "reputation": 60, "items": [{"item_id": "CUSTODIAN_BADGE_SILVER", "quantity": 1}, {"item_id": "SENTINEL_COMM_DEVICE", "quantity": 1}]}'::jsonb, false, false, 'QUEST_NEUTRAL_STORY_003', false, NULL, NULL, NULL, 'quest_neutral.json', 2)
