values ('QUEST_NEUTRAL_SIDE_001', 'A Merchant''s Dilemma', 'side', 'B', 'NEUTRAL', 'NEXUS_CORE', 'Elara Voss at Pax Nexus (Nexus Core — The Common Market) needs a shipment of medical supplies intercepted near the Mid-Zone Skirmish Area. Travel there, recover 5 medical supply crates, eliminate 10 opportunist looters guarding the site, and return to Elara.', '{"npc_id": "NPC_NEXUS_MERCHANT_ELARA", "name": "Elara Voss", "location": "Pax Nexus — The Common Market"}'::jsonb, '{"min_level": 8, "reputation_required": 0, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "travel", "target": "MID_ZONE_SKIRMISH_AREA", "count": 1, "description": "Travel to the Mid-Zone Skirmish Area node on the world map"}, {"type": "collect", "target": "salvaged_supply_crate", "count": 5, "description": "Collect 5x salvaged_supply_crate from the skirmish area drops"}, {"type": "kill", "target": "FERAL_SCAVENGER", "count": 10, "description": "Defeat 10x FERAL_SCAVENGER at the Mid-Zone Skirmish Area"}, {"type": "interact", "target": "NPC_NEXUS_MERCHANT_ELARA", "count": 1, "description": "Return to Elara Voss at Pax Nexus — The Common Market (Nexus Core) (Elara Voss at Pax Nexus — The Common Market)"}]'::jsonb, '{"exp": 500, "currency": 0, "crd": 200, "reputation": 15, "items": [{"item_id": "con_large_hp_cell", "quantity": 5}]}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 5)
