values ('QUEST_NEUTRAL_DAILY_001', 'Border Patrol', 'daily', 'B', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'The Custodians need independent operatives to patrol the border zones near Pax Nexus and report any unusual activity. (Location: Nexus Core, Arbiter Lorn Kael) This is routine work but crucial for maintaining the peace.', '{"npc_id": "NPC_NEXUS_QUESTGIVER_ARBITER", "name": "Arbiter Lorn Kael", "location": "Pax Nexus — The Conclave Hall"}'::jsonb, '{"min_level": 5, "reputation_required": 0, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "kill", "target": "BORDER_RAIDER", "count": 15, "description": "Eliminate {count} border raiders threatening the neutral zone"}, {"type": "travel", "target": "NEXUS_CORE", "count": 1, "description": "Return to report to Arbiter Lorn Kael (Travel to: Nexus Core)"}]'::jsonb, '{"exp": 300, "currency": 0, "crd": 120, "reputation": 10, "items": []}'::jsonb, true, true, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 9)
