values ('QUEST_NEUTRAL_AMA_001', 'Currency Smuggling Investigation', 'faction', 'A', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'The AMA has detected counterfeit CRD circulating in faction markets — a direct attack on the Credent''s integrity. (Location: Nexus Core, NEXON AMA-7) NEXON AMA-7 has pinpointed the likely source: a underground forging operation in the conflict zone. Destroy the counterfeit operation and recover samples for AMA forensic analysis.', '{"npc_id": "NPC_NEXUS_BANKER_AMA7", "name": "NEXON AMA-7", "location": "Pax Nexus — The AMA Exchange Hub"}'::jsonb, '{"min_level": 35, "reputation_required": 100, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "travel", "target": "COUNTERFEIT_FORGE_LOCATION", "count": 1, "description": "Locate the underground counterfeit forge in the conflict zone"}, {"type": "destroy", "target": "COUNTERFEIT_PRESS_MACHINE", "count": 3, "description": "Destroy {count} counterfeit CRD press machines"}, {"type": "kill", "target": "FORGE_GUARD_ELITE", "count": 10, "description": "Eliminate {count} forge guards protecting the operation"}, {"type": "collect", "target": "COUNTERFEIT_CRD_SAMPLE", "count": 5, "description": "Recover 5 counterfeit CRD samples for forensic analysis"}, {"type": "interact", "target": "NPC_NEXUS_BANKER_AMA7", "count": 1, "description": "Submit samples to NEXON AMA-7 for analysis (NEXON AMA-7 at Pax Nexus — The AMA Exchange Hub)"}]'::jsonb, '{"exp": 3000, "currency": 0, "crd": 1500, "reputation": 100, "items": [{"item_id": "AMA_CERTIFICATION_TOKEN", "quantity": 1}]}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 13)
