values ('QUEST_NEUTRAL_AMA_002', 'Stabilize the Market', 'faction', 'S+', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'An economic crisis is brewing: one faction''s currency has collapsed to dangerous lows, threatening galactic trade routes. (Location: Nexus Core, NEXON AMA-7) The AMA is deploying an emergency stabilization package, but needs ground operatives to secure the delivery route and fend off speculators trying to exploit the collapse. This is a party mission.', '{"npc_id": "NPC_NEXUS_BANKER_AMA7", "name": "NEXON AMA-7", "location": "Pax Nexus — The AMA Exchange Hub"}'::jsonb, '{"min_level": 50, "reputation_required": 300, "required_quests": ["QUEST_NEUTRAL_AMA_001"], "party_required": true, "raid_size": 4}'::jsonb, '[{"type": "travel", "target": "CRISIS_FACTION_CAPITAL", "count": 1, "description": "Escort the AMA stabilization convoy to the crisis faction capital"}, {"type": "kill", "target": "ECONOMIC_SPECULATOR_SQUAD", "count": 20, "description": "Eliminate {count} speculator squads attacking the convoy"}, {"type": "interact", "target": "AMA_DELIVERY_TERMINAL", "count": 1, "description": "Deliver the stabilization package to the AMA terminal at the capital"}]'::jsonb, '{"exp": 15000, "currency": 0, "crd": 6000, "reputation": 400, "items": [{"item_id": "AMA_MASTER_SEAL", "quantity": 1}, {"item_id": "CUSTODIAN_LEGENDARY_WEAPON_BOX", "quantity": 1}]}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 14)
