values ('QUEST_NEUTRAL_SPECIAL_001', 'Cross-Faction Trade Summit', 'faction', 'A', 'GALACTIC_CUSTODIANS', 'NEXUS_CORE', 'Ambassador Vael is organizing a trade summit between warring factions. (Location: Nexus Core, Ambassador Vael Drosian) Your job: secure the venue, escort delegates, and prevent assassination attempts. Success means a peace treaty — which the Custodians will reward generously. Your faction will also reward your diplomatic service.', '{"npc_id": "NPC_NEXUS_DIPLOMAT_VAEL", "name": "Ambassador Vael Drosian", "location": "Pax Nexus — The Diplomat''s Quarter"}'::jsonb, '{"min_level": 30, "reputation_required": 150, "required_quests": [], "party_required": false, "raid_size": 1}'::jsonb, '[{"type": "kill", "target": "SUMMIT_DISRUPTOR", "count": 12, "description": "Neutralize {count} summit disruptors before the delegates arrive"}, {"type": "interact", "target": "SUMMIT_DELEGATE_A", "count": 1, "description": "Escort Delegate A safely to the summit hall"}, {"type": "interact", "target": "SUMMIT_DELEGATE_B", "count": 1, "description": "Escort Delegate B safely to the summit hall"}, {"type": "kill", "target": "ASSASSIN_ELITE", "count": 3, "description": "Defeat {count} elite assassins sent to disrupt the summit"}]'::jsonb, '{"exp": 2500, "currency": 400, "crd": 600, "reputation": 120, "items": [{"item_id": "DIPLOMAT_SIGNET_RING", "quantity": 1}], "_reward_note": "currency=400 dibayar dalam mata uang faction player. crd=600 dari Custodian. Dual reward."}'::jsonb, false, false, NULL, false, NULL, NULL, NULL, 'quest_neutral.json', 16)
